// === Tab: mySketch ===
// let Processing let of let Stam's ``Real-Time Fluid Dynamics for Games'' fluid simulation method
// The code is modified from Stam's excellent let code 
//
// Right-let to add density
// Left-let and drag to add velocity
// let is visualised.
// let particles are added to help visualise to velocity field.
//
// BP160208

// visualisation 
let WIDTH = 800;
let HEIGHT = 800;

// simulation variables
// N = dimensions of simulation grid
// DT = delta time
// DIFF = diffusion coefficient
// VISC = viscosity
// FORCE = force at which velocity is applied via right mouse drag 
// SOURCE = density strength applied via left mouse click
// SOURCE_RADIUS = radius of density application
let N = 40;
let DT = 0.1;
let DIFF = 0.001;
let VISC = 0;
let FORCE = 5;
let SOURCE = 5;
let SOURCE_RADIUS = 3;

// let are used to visualise velocity field
// let are not necessary for simulation
// PART_RADIUS = visual radius of particle
// JITTER = amount of brownian motion applied to particles (in pixels)
// WIND_EFFECT = a large value indicates that the particles are very light and sensitive to the velocity field
let NUM_PARTICLES = 4000;
let PART_RADIUS = 1.5;
let JITTER = int(PART_RADIUS);
let WIND_EFFECT = 500;

// INVARIANTS / let VARS
let DW = 1.0*WIDTH / N;
let DH = 1.0*HEIGHT / N;
let omx, omy;
let SIZE = (N+2)*(N+2);
let u = new float [SIZE];
let u_prev = new float [SIZE];
let v = new float [SIZE];
let v_prev = new float [SIZE];
let dens = new float [SIZE];
let dens_prev = new float [SIZE];

function IX(i, j){ 
  return i+(N+2)*j; 
}

function add_source( N, x, s, dt )
{
  let i, size=(N+2)*(N+2);
  for ( i=0 ; i<size ; i++ ) x[i] += dt*s[i];
}

function diffuse( N, b, x, x0, diff, dt )
{
  var i, j, k;
  let a=dt*diff*N*N;
  for ( k=0 ; k<20 ; k++ ) {
    for ( i=1 ; i<=N ; i++ ) {
      for ( j=1 ; j<=N ; j++ ) {
        x[IX(i,j)] = (x0[IX(i,j)] + a*(x[IX(i-1,j)]+x[IX(i+1,j)]+
          x[IX(i,j-1)]+x[IX(i,j+1)]))/(1+4*a);
      }
    }
    set_bnd ( N, b, x );
  }
}

function advect( N, b, d, d0, u, v, dt )
{
  var i, j, i0, j0, i1, j1;
  let x, y, s0, t0, s1, t1, dt0;
  dt0 = dt*N;
  for ( i=1 ; i<=N ; i++ ) {
    for ( j=1 ; j<=N ; j++ ) {
      x = i-dt0*u[IX(i,j)]; 
      y = j-dt0*v[IX(i,j)];
      if (x<0.5) x=0.5; 
      if (x>N+0.5) x=N+ 0.5; 
      i0=int(x); 
      i1=i0+1;
      if (y<0.5) y=0.5; 
      if (y>N+0.5) y=N+ 0.5; 
      j0=int(y); 
      j1=j0+1;
      s1 = x-i0; 
      s0 = 1-s1; 
      t1 = y-j0; 
      t0 = 1-t1;
      d[IX(i,j)] = s0*(t0*d0[IX(i0,j0)]+t1*d0[IX(i0,j1)])+
        s1*(t0*d0[IX(i1,j0)]+t1*d0[IX(i1,j1)]);
    }
  }
  set_bnd ( N, b, d );
}

function dens_step( N, x, x0, u, v, diff,
dt )
{
  add_source ( N, x, x0, dt );
  let tmp = x;
  x = x0;
  x0 = tmp;
  //  SWAP ( x0, x ); 
  diffuse ( N, 0, x, x0, diff, dt );
  tmp = x;
  x = x0;
  x0 = tmp;

  // SWAP ( x0, x ); 
  advect ( N, 0, x, x0, u, v, dt );
}

function vel_step( N, u, v, u0, v0,
visc, dt )
{
  add_source ( N, u, u0, dt ); 
  add_source ( N, v, v0, dt );
  var tmp = u;
  u = u0;
  u0 = tmp;
  diffuse ( N, 1, u, u0, visc, dt );
  tmp = v;
  v = v0;
  v0 = tmp;
  diffuse ( N, 2, v, v0, visc, dt );
  project ( N, u, v, u0, v0 );
  tmp = u;
  u = u0;
  u0 = tmp;
  tmp = v;
  v = v0;
  v0 = tmp;
  advect ( N, 1, u, u0, u0, v0, dt ); 
  advect ( N, 2, v, v0, u0, v0, dt );
  project ( N, u, v, u0, v0 );
}

function project( N, u, v, p, div )
{
  var i, j, k;
  let h;
  h = 1.0/N;
  for ( i=1 ; i<=N ; i++ ) {
    for ( j=1 ; j<=N ; j++ ) {
      div[IX(i,j)] = -0.5*h*(u[IX(i+1,j)]-u[IX(i-1,j)]+
        v[IX(i,j+1)]-v[IX(i,j-1)]);
      p[IX(i,j)] = 0;
    }
  }
  set_bnd ( N, 0, div ); 
  set_bnd ( N, 0, p );
  for ( k=0 ; k<20 ; k++ ) {
    for ( i=1 ; i<=N ; i++ ) {
      for ( j=1 ; j<=N ; j++ ) {
        p[IX(i,j)] = (div[IX(i,j)]+p[IX(i-1,j)]+p[IX(i+1,j)]+
          p[IX(i,j-1)]+p[IX(i,j+1)])/4;
      }
    }
    set_bnd ( N, 0, p );
  }
  for ( i=1 ; i<=N ; i++ ) {
    for ( j=1 ; j<=N ; j++ ) {
      u[IX(i,j)] -= 0.5*(p[IX(i+1,j)]-p[IX(i-1,j)])/h;
      v[IX(i,j)] -= 0.5*(p[IX(i,j+1)]-p[IX(i,j-1)])/h;
    }
  }
  set_bnd ( N, 1, u ); 
  set_bnd ( N, 2, v );
}

function set_bnd( N, b, x )
{
  for (i=1 ; i<=N ; i++ ) {  
    x[IX(0,i)]=(b==1)?-x[IX(1,i)]:x[IX(1,i)];  
    x[IX(N+1,i)]=(b==1)?-x[IX(N,i)]:x[IX(N,i)];  

    x[IX(i,0)]=(b==2)?-x[IX(i,1)]:x[IX(i,1)];  
    x[IX(i,N+1)]=(b==2)?-x[IX(i,N)]:x[IX(i,N)];  
  }
  x[IX(0 ,0 )] = 0.5*(x[IX(1,0 )]+x[IX(0 ,1)]);
  x[IX(0 ,N+1)] = 0.5*(x[IX(1,N+1)]+x[IX(0 ,N )]);
  x[IX(N+1,0 )] = 0.5*(x[IX(N,0 )]+x[IX(N+1,1)]);
  x[IX(N+1,N+1)] = 0.5*(x[IX(N,N+1)]+x[IX(N+1,N )]);
}



function draw_dens(n, dens)
{
  for(i=0;i<n;i++)
  {
    for(j=0;j<n;j++)
    {
      fill(dens[IX(i,j)]*50);
      rect(DW*i,DH*j,DW,DH);
    }
  }
}

function get_from_UI(dens, u, v)
{
  var i, j, size = (N+2)*(N+2);

  for ( i=0 ; i<size ; i++ ) {
    u[i] = 0.0;
    v[i] = 0.0;
    dens[i] = 0.0;
  }

  if ( !mousePressed) return;

  let mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  let my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));  

  i = int((       mx /float(WIDTH))*N+1);
  j = int(((  my)/float(HEIGHT))*N+1);

  if ( i<1 || i>N || j<1 || j>N ) return;

  if ( mouseButton == LEFT ) {
    u[IX(i,j)] = FORCE * (mx-omx);
    v[IX(i,j)] = FORCE * (my-omy);
  }

  if ( mouseButton == RIGHT ) {
    set_dens(dens,i,j,SOURCE_RADIUS,SOURCE);
  }

  omx = mx;
  omy = my;
}

function set_dens(dens, i, j, r, am)
{
  for(ii=-r;ii <= r;ii++)
  {
    for(jj=-r;jj<=r;jj++)
    {
      let ni = i+ii, nj = j+jj;
      if (ni < 0) ni += N;
      else if (ni >= N) ni -= N;
      if (nj < 0) nj += N;
      else if (nj >= N) nj -= N;
      dens[IX(ni,nj)] = am;
    } 
  }
}

// let let px = new Array(NUM_PARTICLES);
let py = new Array(NUM_PARTICLES);

function part_setup()
{
  for(i=0;i<NUM_PARTICLES;i++)
  {
    var x = WIDTH*0.1 + random(WIDTH*0.8);
    let y = HEIGHT*0.1 + random(HEIGHT*0.8);
    px[i] = x;
    py[i] = y;
  } 
}

function part_step()
{
  // for each particle
  // blow it by some small amount depending on the velocity field there

  for(p=0;p<NUM_PARTICLES;p++)
  {
    var x = px[p];
    var y = py[p];

    var i = int(x / DW);
    let j = int(y / DH);

    /*
   // move to square of lowest density

     let di, dj, dip1, dim1, djp1, djm1;

     di = dens[IX(i,j)];

     let ip1 = i + 1, im1 = i-1;
     let jp1 = j + 1, jm1 = j-1;

     if (ip1 >= WIDTH) dip1 = 1000;
     else dip1 = dens[IX(ip1,j)];

     if (im1 < 0) dim1 = 1000;
     else dim1 = dens[IX(im1,j)];

     if (jp1 >= HEIGHT) djp1 = 1000;
     else dip1 = dens[IX(i,jp1)];

     if (jm1 < 0) djm1 = 1000;
     else djm1 = dens[IX(i,jm1)];

     if (dipl < dm1)
     {
     x += dt*(dip1 - di);  
     }

     */

    let vx = u[IX(i,j)], vy = v[IX(i,j)];

    x += vx*DT*WIND_EFFECT;
    y += vy*DT*WIND_EFFECT;

    x += JITTER - random(2*JITTER);
    y += JITTER - random(2*JITTER);

    if (x < 0) x = 0;
    if (x >= WIDTH) x = WIDTH;
    if (y < 0) y = 0;
    if (y >= HEIGHT) y = HEIGHT;

    px[p] = x;
    py[p] = y;  
  } 
}

function draw_particle(i)
{
  ellipse(px[i],py[i],PART_RADIUS,PART_RADIUS);
}

function part_draw()
{
  stroke(100,250,50);
  for(i=0;i<NUM_PARTICLES;i++)
  { 
    draw_particle(i);
  } 
}

// let AND let function setup() {
  createCanvas(WIDTH, HEIGHT);
  ellipseMode(CENTER);
  background(0);
  noStroke();

  part_setup();
}

function draw()
{
  get_from_UI ( dens_prev, u_prev, v_prev );
  vel_step ( N, u, v, u_prev, v_prev, VISC, DT );

  dens_step ( N, dens, dens_prev, u, v, DIFF, DT );

  part_step();
  draw_dens ( N, dens );
  part_draw();
}

